INSERT INTO `ai_knowledge` (`id`, `table_name`, `purpose`, `columns_info`, `hints`, `enabled`, `created_at`, `updated_at`, `is_deleted`) VALUES
  (1, 'doctors', 'Doctors who work at the hospital.', 'id, doctor_code, first_name, last_name, email, phone, gender, qualification, experience_years, consultation_fee, is_deleted', 'Always filter is_deleted = false. A doctor\'s specialty is found by joining to specialties through doctor_specialties_map.', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (2, 'specialties', 'Medical specialties, e.g. Cardiology, Neurology.', 'id, name, description, is_deleted', 'The specialty name is in specialties.name (e.g. \'Cardiology\'). Filter is_deleted = false.', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (3, 'doctor_specialties_map', 'Link table connecting doctors and specialties (many-to-many).', 'id, doctor_id, specialty_id', 'Join doctors.id = doctor_specialties_map.doctor_id and specialties.id = doctor_specialties_map.specialty_id.', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (4, 'patient', 'Patients registered at the hospital.', 'id, patient_code, first_name, last_name, date_of_birth, gender, phone, email, address, blood_group, is_deleted', 'Filter is_deleted = false. Table name is singular: patient.', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (5, 'appointments', 'Appointments between a patient and a doctor.', 'id, patient_id, doctor_id, appointment_date, start_time, end_time, duration_minutes, status, is_deleted', 'Join appointments.doctor_id = doctors.id and appointments.patient_id = patient.id. status is an enum. Filter is_deleted = false.', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (6, 'doctor_availabilities', 'The weekly working hours of each doctor: which days they work, from when to when, and their daily break.', 'id, doctor_id, day_of_week, start_time, end_time, break_start_time, break_end_time, is_deleted', 'Join doctor_availabilities.doctor_id = doctors.id. Filter is_deleted = false. day_of_week is text holding an uppercase English day name: MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY, SATURDAY, SUNDAY - compare it as a string, never as a number. start_time and end_time are TIME columns (e.g. 09:00:00) and are never null. break_start_time and break_end_time are TIME columns that CAN be null, meaning that day has no break - use them only with a null check. There is at most ONE row per doctor per day (unique on doctor_id + day_of_week), so counting rows for a doctor gives the number of days they work. A doctor with no row for a day does not work that day. To ask about today, compare day_of_week to UPPER(DAYNAME(CURDATE())). Working minutes for a day = TIMESTAMPDIFF(MINUTE, start_time, end_time) minus the break when both break columns are set.', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0);
INSERT INTO `ai_prompt_example` (`id`, `question`, `generated_sql`, `enabled`, `created_at`, `updated_at`, `is_deleted`) VALUES
  (1, 'count all doctors', 'SELECT count(*) AS `Total Doctors` FROM doctors WHERE is_deleted = false', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (2, 'list all cardiology doctors', 'SELECT d.first_name AS `First Name`, d.last_name AS `Last Name`, d.email AS `Email` FROM doctors d JOIN doctor_specialties_map m ON m.doctor_id = d.id JOIN specialties s ON s.id = m.specialty_id WHERE d.is_deleted = false AND s.name = \'Cardiology\'', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (3, 'list all patients', 'SELECT first_name AS `First Name`, last_name AS `Last Name`, email AS `Email` FROM patient WHERE is_deleted = false', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (4, 'list doctor availability timing', 'SELECT d.first_name AS `First Name`, d.last_name AS `Last Name`, av.day_of_week AS `Day`, av.start_time AS `Starts`, av.end_time AS `Ends` FROM doctor_availabilities av JOIN doctors d ON d.id = av.doctor_id WHERE av.is_deleted = false AND d.is_deleted = false ORDER BY d.first_name, av.day_of_week', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (5, 'which doctors are available today', 'SELECT d.first_name AS `First Name`, d.last_name AS `Last Name`, av.start_time AS `Starts`, av.end_time AS `Ends` FROM doctor_availabilities av JOIN doctors d ON d.id = av.doctor_id WHERE av.is_deleted = false AND d.is_deleted = false AND av.day_of_week = UPPER(DAYNAME(CURDATE()))', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (6, 'how many days does each doctor work', 'SELECT d.first_name AS `First Name`, d.last_name AS `Last Name`, COUNT(*) AS `Working Days` FROM doctor_availabilities av JOIN doctors d ON d.id = av.doctor_id WHERE av.is_deleted = false AND d.is_deleted = false GROUP BY d.id, d.first_name, d.last_name ORDER BY `Working Days` DESC', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (7, 'total weekly working hours for each doctor', 'SELECT d.first_name AS `First Name`, d.last_name AS `Last Name`, SUM(TIMESTAMPDIFF(MINUTE, av.start_time, av.end_time) - COALESCE(TIMESTAMPDIFF(MINUTE, av.break_start_time, av.break_end_time), 0)) / 60 AS `Weekly Hours` FROM doctor_availabilities av JOIN doctors d ON d.id = av.doctor_id WHERE av.is_deleted = false AND d.is_deleted = false GROUP BY d.id, d.first_name, d.last_name ORDER BY `Weekly Hours` DESC', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0);
INSERT INTO `app_setting` (`id`, `name`, `setting_value`, `secret`, `description`, `enabled`, `created_at`, `updated_at`, `is_deleted`) VALUES
  (1, 'nim.model', 'nvidia/nemotron-3-super-120b-a12b', 0, 'NIM model used for text-to-SQL', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (2, 'nim.base-url', 'https://integrate.api.nvidia.com/v1', 0, 'NVIDIA NIM OpenAI-compatible base URL', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (3, 'nim.api-key', 'paste api key here', 1, 'NVIDIA NIM API key', 1, '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0);
INSERT INTO `widget` (`id`, `code`, `name`, `description`, `module`, `type`, `status`, `enabled`, `filters`, `sql_template`, `created_at`, `updated_at`, `is_deleted`) VALUES
  (1, 'specialty-list', 'Specialty List', 'Lists medical specialties; optional name filter.', 'WIDGET', 'TABLE', 'APPROVED', 1, '{"filters":[{"key":"name","operators":["eq","like"]}],"sortableColumns":["Specialty"]}', 'SELECT name AS `Specialty`, description AS `Details` FROM specialties WHERE is_deleted = false AND name {{name}} coalesce(:name, name)', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (2, 'doctor-appointment-schedule', 'Doctor Appointment Schedule', 'List doctors with their patient appointment schedule', 'WIDGET', 'TABLE', 'APPROVED', 1, '{"filters":[{"key":"doctorId","label":"Doctor","type":"number","operators":["eq"],"required":false},{"key":"appointmentDate","label":"Appointment Date","type":"date","operators":["eq"],"required":false},{"key":"status","label":"Status","type":"string","operators":["eq","in"],"required":false}],"sortableColumns":["Doctor Name","Patient Name","Appointment Date","Start Time","End Time","Duration (Min)","Status"]}', 'SELECT CONCAT(d.first_name, \' \', d.last_name) AS `Doctor Name`, CONCAT(p.first_name, \' \', p.last_name) AS `Patient Name`, DATE_FORMAT(a.appointment_date, \'%d %b %Y\') AS `Appointment Date`, DATE_FORMAT(a.start_time, \'%h:%i %p\') AS `Start Time`, DATE_FORMAT(a.end_time, \'%h:%i %p\') AS `End Time`, CONCAT(a.duration_minutes, \' min\') AS `Duration`, a.status AS `Status` FROM appointments a JOIN doctors d ON d.id = a.doctor_id JOIN patient p ON p.id = a.patient_id WHERE d.is_deleted = false AND a.is_deleted = false AND d.id {{doctorId}} COALESCE(:doctorId, d.id) AND a.appointment_date {{appointmentDate}} COALESCE(:appointmentDate, a.appointment_date) AND a.status {{status}} COALESCE(:status, a.status)', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (3, 'appointment-status-distribution', 'Appointment Status Distribution', 'Distribution of appointments by status', 'WIDGET', 'PIE', 'APPROVED', 1, '{"filters":[],"sortableColumns":[]}', 'SELECT a.status AS `Status`, COUNT(*) AS `Total` FROM appointments a WHERE a.is_deleted = false GROUP BY a.status ORDER BY a.status', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (4, 'total-active-doctors', 'Total Active Doctors', 'Total number of active doctors', 'WIDGET', 'COUNT', 'APPROVED', 1, NULL, 'SELECT COUNT(*) AS `Total Doctors` FROM doctors WHERE is_deleted = false', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (5, 'total-active-patients', 'Total Active Patients', 'Total number of active patients', 'WIDGET', 'COUNT', 'APPROVED', 1, NULL, 'SELECT COUNT(*) AS `Total Patients` FROM patient WHERE is_deleted = false', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0);
INSERT INTO `widget` (`id`, `code`, `name`, `description`, `module`, `type`, `status`, `enabled`, `filters`, `sql_template`, `created_at`, `updated_at`, `is_deleted`) VALUES
  (6, 'todays-appointments', 'Today\'s Appointments', 'Total appointments scheduled for today', 'WIDGET', 'COUNT', 'APPROVED', 1, NULL, 'SELECT COUNT(*) AS `Today\'s Appointments` FROM appointments WHERE is_deleted = false AND appointment_date = CURDATE()', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (7, 'appointments-by-specialty', 'Appointments by Specialty', 'Number of appointments grouped by medical specialty', 'WIDGET', 'BAR', 'APPROVED', 1, '{"filters":[],"sortableColumns":["Specialty","Appointments"]}', 'SELECT s.name AS `Specialty`, COUNT(a.id) AS `Appointments` FROM appointments a JOIN doctors d ON d.id = a.doctor_id JOIN doctor_specialties_map dsm ON dsm.doctor_id = d.id JOIN specialties s ON s.id = dsm.specialty_id WHERE a.is_deleted = false AND d.is_deleted = false AND s.is_deleted = false GROUP BY s.id, s.name ORDER BY `Appointments` DESC', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (8, 'appointments-by-doctor', 'Appointments by Doctor', 'Number of appointments for each doctor', 'WIDGET', 'BAR', 'APPROVED', 1, '{"filters":[],"sortableColumns":["Doctor","Appointments"]}', 'SELECT CONCAT(d.first_name, \' \', d.last_name) AS `Doctor`, COUNT(a.id) AS `Appointments` FROM appointments a JOIN doctors d ON d.id = a.doctor_id WHERE a.is_deleted = false AND d.is_deleted = false GROUP BY d.id, d.first_name, d.last_name ORDER BY `Appointments` DESC', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (9, 'appointments-last-30-days', 'Appointments - Last 30 Days', 'Daily appointment trend for the last 30 days', 'WIDGET', 'LINE', 'APPROVED', 1, '{"filters":[],"sortableColumns":["Date","Appointments"]}', 'SELECT a.appointment_date AS `Date`, COUNT(*) AS `Appointments` FROM appointments a WHERE a.is_deleted = false AND a.appointment_date >= CURDATE() - INTERVAL 29 DAY AND a.appointment_date <= CURDATE() GROUP BY a.appointment_date ORDER BY a.appointment_date', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (10, 'doctors-by-specialty', 'Doctors by Specialty', 'Number of active doctors in each specialty', 'WIDGET', 'BAR', 'APPROVED', 1, '{"filters":[],"sortableColumns":["Specialty","Doctors"]}', 'SELECT s.name AS `Specialty`, COUNT(DISTINCT d.id) AS `Doctors` FROM doctors d JOIN doctor_specialties_map dsm ON dsm.doctor_id = d.id JOIN specialties s ON s.id = dsm.specialty_id WHERE d.is_deleted = false AND s.is_deleted = false GROUP BY s.id, s.name ORDER BY `Doctors` DESC', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0);
INSERT INTO `widget` (`id`, `code`, `name`, `description`, `module`, `type`, `status`, `enabled`, `filters`, `sql_template`, `created_at`, `updated_at`, `is_deleted`) VALUES
  (11, 'scheduled-appointments', 'Scheduled Appointments', 'Total number of scheduled appointments', 'WIDGET', 'COUNT', 'APPROVED', 1, NULL, 'SELECT COUNT(*) AS `Scheduled Appointments` FROM appointments WHERE is_deleted = false AND status = \'SCHEDULED\'', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (12, 'completed-appointments', 'Completed Appointments', 'Total number of completed appointments', 'WIDGET', 'COUNT', 'APPROVED', 1, NULL, 'SELECT COUNT(*) AS `Completed Appointments` FROM appointments WHERE is_deleted = false AND status = \'COMPLETED\'', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (13, 'patient-gender-distribution', 'Patient Gender Distribution', 'Number of active patients by gender', 'WIDGET', 'BAR', 'APPROVED', 1, '{"filters":[],"sortableColumns":["Gender","Patients"]}', 'SELECT gender AS `Gender`, COUNT(*) AS `Patients` FROM patient WHERE is_deleted = false GROUP BY gender ORDER BY `Patients` DESC', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (14, 'monthly-appointments', 'Monthly Appointments', 'Monthly appointment trend', 'WIDGET', 'LINE', 'APPROVED', 1, '{"filters":[],"sortableColumns":["Month","Appointments"]}', 'SELECT DATE_FORMAT(a.appointment_date, \'%Y-%m\') AS `Month`, COUNT(*) AS `Appointments` FROM appointments a WHERE a.is_deleted = false AND a.appointment_date >= DATE_SUB(CURDATE(), INTERVAL 11 MONTH) GROUP BY DATE_FORMAT(a.appointment_date, \'%Y-%m\') ORDER BY `Month`', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (15, 'list-all-patients-with-their-blood-group', 'list all patients with their blood group', 'list all patients with their blood group', 'PROMPT', 'TABLE', 'APPROVED', 1, NULL, 'SELECT first_name AS `First Name`, last_name AS `Last Name`, blood_group AS `Blood Group` FROM patient WHERE is_deleted = false', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0);
