-- ---------- ai_prompt_example (question -> known-good SQL) ----------

-- ---------- app_setting ----------
-- nim.api-key is seeded with a PLACEHOLDER value, not a real key. Replace it after
-- loading - see the note at the top of this file.

-- ---------- widget (20: 14 hand-built + 6 AI-generated) ----------



FROM doctors d
JOIN appointments a ON a.doctor_id = d.id
WHERE d.is_deleted = false
  AND a.is_deleted = false
GROUP BY d.id, d.first_name, d.last_name
ORDER BY appointment_count DESC
LIMIT 5', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (18, 'how-many-doctors-work-on-sunday', 'how many doctors work on sunday', 'how many doctors work on sunday', 'PROMPT', 'TABLE', 'APPROVED', 1, NULL, 'SELECT COUNT(DISTINCT d.id) AS `Doctors Working On Sunday` FROM doctor_availabilities av JOIN doctors d ON d.id = av.doctor_id WHERE av.is_deleted = false AND d.is_deleted = false AND av.day_of_week = \'SUNDAY\'', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (19, 'i-want-all-doctor-all-day-working-time-and-doctor-firstname-and-lastname-as-name', 'Doctor working Time', 'i want all doctor all day working time and doctor firstname and lastname as name', 'PROMPT', 'TABLE', 'APPROVED', 1, NULL, 'SELECT CONCAT(d.first_name, \' \', d.last_name) AS Name,
       av.day_of_week AS Day,
       (TIMESTAMPDIFF(MINUTE, av.start_time, av.end_time) - COALESCE(TIMESTAMPDIFF(MINUTE, av.break_start_time, av.break_end_time), 0)) AS WorkingTime
FROM doctor_availabilities av
JOIN doctors d ON d.id = av.doctor_id
WHERE av.is_deleted = false
  AND d.is_deleted = false
ORDER BY d.first_name, d.last_name, av.day_of_week', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0),
  (20, 'list-only-cardiology-doctor-available-on-monday-also-can-you-join-firstname-and-lastname-as-name-also-its-timing', 'Doctor Available on Monday', 'list  only cardiology doctor available on monday also can you join firstname and lastname as name also its timing', 'PROMPT', 'TABLE', 'APPROVED', 1, NULL, 'SELECT CONCAT(d.first_name, \' \', d.last_name) AS `Name`, av.start_time AS `Start Time`, av.end_time AS `End Time`
FROM doctors d
JOIN doctor_specialties_map m ON m.doctor_id = d.id
JOIN specialties s ON s.id = m.specialty_id
JOIN doctor_availabilities av ON av.doctor_id = d.id
WHERE d.is_deleted = false
  AND s.is_deleted = false
  AND av.is_deleted = false
  AND s.name = \'Cardiology\'
  AND av.day_of_week = \'MONDAY\'', '2026-08-01 09:00:00.000000', '2026-08-01 09:00:00.000000', 0);

